function solve({config,state,event}){
  var c=config;
  if(state===null)state={v:c.initial,d:String(c.initial),e:null,x:false};
  var s={v:state.v,d:state.d,e:state.e,x:state.x},t=event.type;
  var count=Math.floor((c.max-c.min)/c.step),last=c.min+count*c.step;
  if(t==='mode')s.x=event.disabled;
  else if(t==='cancel'){s.d=String(s.v);s.e=null}
  else if(!s.x&&t==='input'){s.d=event.text;s.e=null}
  else if(!s.x&&t==='commit'){
    var ok=/^[+-]?[0-9]+$/.test(s.d),n=ok?Number(s.d):NaN;
    if(!ok||!Number.isSafeInteger(n))s.e='invalid';
    else{
      var i=Math.floor((n-c.min)/c.step);
      if(i<0)i=0;
      if(i>count)i=count;
      var a=c.min+i*c.step;
      if(i<count){var b=a+c.step;if(n-a>b-n)a=b}
      s.v=a;s.d=String(a);s.e=null;
    }
  }else if(!s.x&&t==='step'){
    var i=Math.round((s.v-c.min)/c.step)+(event.direction<0?-1:1);
    if(i<0)i=0;if(i>count)i=count;
    s.v=c.min+i*c.step;s.d=String(s.v);s.e=null;
  }
  return {state:s,output:{value:s.v,draft:s.d,dirty:s.d!==String(s.v),error:s.e,disabled:s.x}};
}
